{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Security group ingress rule missing description",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The dynamic ingress block does not include a 'description' argument. While the security group itself has a description, individual rules should also be described for auditability and clarity."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Ingress open to world (0.0.0.0/0)",
      "resource": "aws_security_group.vault",
      "severity": "HIGH",
      "explanation": "The ingress rules allow traffic from any IPv4 address (0.0.0.0/0) on the specified ports. This exposes the Vault service to the entire internet, which is a significant security risk unless strictly intended and mitigated by other controls."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"vault\" {\n  name        = \"vault\"\n  description = \"Ingress for Vault\"\n  vpc_id      = aws_vpc.my_vpc.id\n  dynamic \"ingress\" {\n    iterator = port\n    for_each = var.ingress_ports\n    content {\n      from_port   = port.value\n      to_port     = port.value\n      protocol    = \"tcp\"\n      cidr_blocks = [\"0.0.0.0/0\"]\n      description = \"Allow ${port.value} from anywhere\"\n    }\n  }\n}",
  "fix_summary": "Added a 'description' field to the dynamic ingress block to satisfy CKV_AWS_23. Note: The high-severity finding regarding 0.0.0.0/0 exposure was reported but not patched in the code because changing the CIDR range requires specific business context (e.g., valid IP ranges or VPC peering details) that is not available in this snippet; hardcoding a different value would break functionality or introduce incorrect assumptions."
}
